var data = {lines:[
{"lineNum":"    1","line":"#!/usr/bin/env bash"},
{"lineNum":"    2","line":"#"},
{"lineNum":"    3","line":"# nopasswd-sudo.sh — toggle temporary passwordless sudo for a user."},
{"lineNum":"    4","line":"#"},
{"lineNum":"    5","line":"# Handy during migration/maintenance sessions that run many sudo commands"},
{"lineNum":"    6","line":"# non-interactively (e.g. driven over SSH). Turn it ON at the start, OFF when"},
{"lineNum":"    7","line":"# done. The drop-in is validated with `visudo` before being installed, so a"},
{"lineNum":"    8","line":"# typo can\'t lock you out of sudo."},
{"lineNum":"    9","line":"#"},
{"lineNum":"   10","line":"# Enabling also arms an auto-revoke so you can never leave passwordless sudo on"},
{"lineNum":"   11","line":"# by accident: an in-session timer switches it OFF after the timeout (default"},
{"lineNum":"   12","line":"# 30 min; pass a different number of minutes, or 0 to disable), AND a persistent"},
{"lineNum":"   13","line":"# boot-time unit clears it on every reboot. The in-session timer is transient"},
{"lineNum":"   14","line":"# and does NOT survive a reboot, so the boot unit is the reboot safety net —"},
{"lineNum":"   15","line":"# without it, a reboot would strand the grant with nothing left to revoke it."},
{"lineNum":"   16","line":"#"},
{"lineNum":"   17","line":"# Usage:"},
{"lineNum":"   18","line":"#   sudo ./nopasswd-sudo.sh on   [user] [minutes]   # default user: $SUDO_USER, default 30 min"},
{"lineNum":"   19","line":"#   sudo ./nopasswd-sudo.sh off"},
{"lineNum":"   20","line":"#   sudo ./nopasswd-sudo.sh status"},
{"lineNum":"   21","line":"#"},
{"lineNum":"   22","line":"set -o errexit","class":"lineCov","hits":"1","order":"2924",},
{"lineNum":"   23","line":"set -o nounset","class":"lineCov","hits":"1","order":"2933",},
{"lineNum":"   24","line":"set -o pipefail","class":"lineCov","hits":"1","order":"2921",},
{"lineNum":"   25","line":""},
{"lineNum":"   26","line":"# shellcheck source=../../lib/core.sh"},
{"lineNum":"   27","line":"source \"$(cd \"$(dirname \"$0\")\" && pwd -P)/../../lib/core.sh\"","class":"lineCov","hits":"1","order":"2937",},
{"lineNum":"   28","line":"# @include ../../lib/core.sh"},
{"lineNum":"   29","line":""},
{"lineNum":"   30","line":"# The two paths this writes to are taken from the environment when set. Both are system-wide and one of"},
{"lineNum":"   31","line":"# them governs sudo itself, so being able to point them elsewhere is what allows the grant, the revoke and"},
{"lineNum":"   32","line":"# the boot unit to be exercised without touching a real machine\'s sudoers; unset, they are the real ones."},
{"lineNum":"   33","line":": \"${DROPIN:=/etc/sudoers.d/99-temp-nopasswd}\"","class":"lineCov","hits":"1","order":"2944",},
{"lineNum":"   34","line":": \"${SYSTEMD_UNIT_DIR:=/etc/systemd/system}\"","class":"lineCov","hits":"1","order":"2928",},
{"lineNum":"   35","line":"readonly DROPIN SYSTEMD_UNIT_DIR","class":"lineCov","hits":"1","order":"2930",},
{"lineNum":"   36","line":"readonly AUTO_UNIT=\"nopasswd-sudo-autorevoke\"","class":"lineCov","hits":"1","order":"2936",},
{"lineNum":"   37","line":"readonly BOOT_UNIT=\"nopasswd-sudo-bootrevoke\"","class":"lineCov","hits":"1","order":"2939",},
{"lineNum":"   38","line":"readonly DEFAULT_TIMEOUT_MIN=30","class":"lineCov","hits":"1","order":"2946",},
{"lineNum":"   39","line":""},
{"lineNum":"   40","line":"#######################################"},
{"lineNum":"   41","line":"# Log an informational message to stdout."},
{"lineNum":"   42","line":"#######################################"},
{"lineNum":"   43","line":""},
{"lineNum":"   44","line":"#######################################"},
{"lineNum":"   45","line":"# Print usage information."},
{"lineNum":"   46","line":"#######################################"},
{"lineNum":"   47","line":"show_usage() {"},
{"lineNum":"   48","line":"  cat <<EOF","class":"lineCov","hits":"1","order":"2932",},
{"lineNum":"   49","line":"Usage: sudo $(basename \"$0\") {on|off|status} [user] [minutes]"},
{"lineNum":"   50","line":""},
{"lineNum":"   51","line":"  on [user] [minutes]   grant passwordless sudo (default user: \\${SUDO_USER:-root})"},
{"lineNum":"   52","line":"                        and arm auto-revoke after [minutes] (default ${DEFAULT_TIMEOUT_MIN}; 0 = never)"},
{"lineNum":"   53","line":"  off                   revoke it now (removes ${DROPIN}, cancels the timer)"},
{"lineNum":"   54","line":"  status                show whether it is enabled and any armed auto-revoke"},
{"lineNum":"   55","line":""},
{"lineNum":"   56","line":"Examples:"},
{"lineNum":"   57","line":"  sudo $(basename \"$0\") on            # enable for \\$SUDO_USER, auto-off in ${DEFAULT_TIMEOUT_MIN} min"},
{"lineNum":"   58","line":"  sudo $(basename \"$0\") on 90         # enable for \\$SUDO_USER, auto-off in 90 min"},
{"lineNum":"   59","line":"  sudo $(basename \"$0\") on jure 0     # enable for jure, no auto-revoke"},
{"lineNum":"   60","line":"EOF"},
{"lineNum":"   61","line":"}"},
{"lineNum":"   62","line":""},
{"lineNum":"   63","line":"#######################################"},
{"lineNum":"   64","line":"# Abort unless running as root."},
{"lineNum":"   65","line":"#######################################"},
{"lineNum":"   66","line":"require_root() {"},
{"lineNum":"   67","line":"  if [[ \"${EUID}\" -ne 0 ]]; then","class":"lineCov","hits":"1","order":"2949",},
{"lineNum":"   68","line":"    log_error \"must run as root (use sudo).\"","class":"lineNoCov","hits":"0",},
{"lineNum":"   69","line":"    exit 1","class":"lineNoCov","hits":"0",},
{"lineNum":"   70","line":"  fi"},
{"lineNum":"   71","line":"}"},
{"lineNum":"   72","line":""},
{"lineNum":"   73","line":"#######################################"},
{"lineNum":"   74","line":"# Enable passwordless sudo for a user via a validated sudoers drop-in."},
{"lineNum":"   75","line":"# Globals:"},
{"lineNum":"   76","line":"#   DROPIN"},
{"lineNum":"   77","line":"# Arguments:"},
{"lineNum":"   78","line":"#   Target user (defaults to ${SUDO_USER})."},
{"lineNum":"   79","line":"#######################################"},
{"lineNum":"   80","line":"enable_nopasswd() {"},
{"lineNum":"   81","line":"  local user=\"${1:-${SUDO_USER:-}}\"","class":"lineCov","hits":"1","order":"2925",},
{"lineNum":"   82","line":"  if [[ -z \"${user}\" ]]; then","class":"lineCov","hits":"1","order":"2935",},
{"lineNum":"   83","line":"    log_error \"could not determine target user; pass one explicitly.\"","class":"lineCov","hits":"1","order":"2920",},
{"lineNum":"   84","line":"    exit 1","class":"lineCov","hits":"1","order":"2918",},
{"lineNum":"   85","line":"  fi"},
{"lineNum":"   86","line":"  if ! id -u \"${user}\" >/dev/null 2>&1; then","class":"lineCov","hits":"1","order":"2917",},
{"lineNum":"   87","line":"    log_error \"no such user: ${user}\"","class":"lineCov","hits":"1","order":"2916",},
{"lineNum":"   88","line":"    exit 1","class":"lineCov","hits":"1","order":"2915",},
{"lineNum":"   89","line":"  fi"},
{"lineNum":"   90","line":""},
{"lineNum":"   91","line":"  local tmp","class":"lineCov","hits":"1","order":"2943",},
{"lineNum":"   92","line":"  tmp=\"$(mktemp)\"","class":"lineCov","hits":"1","order":"2945",},
{"lineNum":"   93","line":"  printf \'%s ALL=(ALL) NOPASSWD:ALL\\n\' \"${user}\" >\"${tmp}\"","class":"lineCov","hits":"1","order":"2927",},
{"lineNum":"   94","line":""},
{"lineNum":"   95","line":"  # Validate BEFORE installing — a bad sudoers file can lock you out of sudo."},
{"lineNum":"   96","line":"  if ! visudo -cf \"${tmp}\" >/dev/null; then","class":"lineCov","hits":"1","order":"2941",},
{"lineNum":"   97","line":"    rm -f \"${tmp}\"","class":"lineCov","hits":"1","order":"2948",},
{"lineNum":"   98","line":"    log_error \"sudoers syntax check failed; not installing.\"","class":"lineCov","hits":"1","order":"2922",},
{"lineNum":"   99","line":"    exit 1","class":"lineCov","hits":"1","order":"2914",},
{"lineNum":"  100","line":"  fi"},
{"lineNum":"  101","line":""},
{"lineNum":"  102","line":"  install -m 0440 -o root -g root \"${tmp}\" \"${DROPIN}\"","class":"lineCov","hits":"1","order":"2913",},
{"lineNum":"  103","line":"  rm -f \"${tmp}\"","class":"lineCov","hits":"1","order":"2952",},
{"lineNum":"  104","line":"  log_info \"passwordless sudo ENABLED for \'${user}\' (${DROPIN}).\"","class":"lineCov","hits":"1","order":"2954",},
{"lineNum":"  105","line":"}"},
{"lineNum":"  106","line":""},
{"lineNum":"  107","line":"#######################################"},
{"lineNum":"  108","line":"# Arm a one-shot systemd timer that runs `off` after the timeout."},
{"lineNum":"  109","line":"# A transient timer is used so it survives this script (and the SSH session)"},
{"lineNum":"  110","line":"# exiting. Re-arming first cancels any existing timer, resetting the clock."},
{"lineNum":"  111","line":"# Globals:"},
{"lineNum":"  112","line":"#   AUTO_UNIT"},
{"lineNum":"  113","line":"# Arguments:"},
{"lineNum":"  114","line":"#   Timeout in minutes (0 disables auto-revoke)."},
{"lineNum":"  115","line":"#######################################"},
{"lineNum":"  116","line":"schedule_revoke() {"},
{"lineNum":"  117","line":"  local minutes=\"${1}\"","class":"lineCov","hits":"1","order":"2955",},
{"lineNum":"  118","line":"  cancel_revoke","class":"lineCov","hits":"1","order":"2956",},
{"lineNum":"  119","line":"  if [[ \"${minutes}\" -eq 0 ]]; then","class":"lineCov","hits":"1","order":"2957",},
{"lineNum":"  120","line":"    log_info \"auto-revoke DISABLED (timeout 0) — remember to run \'off\' yourself.\"","class":"lineCov","hits":"1","order":"2959",},
{"lineNum":"  121","line":"    return","class":"lineCov","hits":"1","order":"2962",},
{"lineNum":"  122","line":"  fi"},
{"lineNum":"  123","line":"  local self","class":"lineCov","hits":"1","order":"2964",},
{"lineNum":"  124","line":"  self=\"$(readlink -f \"$0\")\"","class":"lineCov","hits":"1","order":"2966",},
{"lineNum":"  125","line":"  local -a args=(--quiet --unit=\"${AUTO_UNIT}\" --on-active=\"${minutes}min\")","class":"lineCov","hits":"1","order":"2967",},
{"lineNum":"  126","line":"  args+=(--description=\"Auto-revoke temporary passwordless sudo\")","class":"lineCov","hits":"1","order":"2950",},
{"lineNum":"  127","line":"  args+=(\"${self}\" off)","class":"lineCov","hits":"1","order":"2951",},
{"lineNum":"  128","line":"  systemd-run \"${args[@]}\"","class":"lineCov","hits":"1","order":"2923",},
{"lineNum":"  129","line":"  log_info \"auto-revoke ARMED: passwordless sudo self-disables in ${minutes} min.\"","class":"lineCov","hits":"1","order":"2969",},
{"lineNum":"  130","line":"}"},
{"lineNum":"  131","line":""},
{"lineNum":"  132","line":"#######################################"},
{"lineNum":"  133","line":"# Cancel any pending auto-revoke timer (idempotent)."},
{"lineNum":"  134","line":"# Globals:"},
{"lineNum":"  135","line":"#   AUTO_UNIT"},
{"lineNum":"  136","line":"#######################################"},
{"lineNum":"  137","line":"cancel_revoke() {"},
{"lineNum":"  138","line":"  systemctl stop \"${AUTO_UNIT}.timer\" >/dev/null 2>&1 || true","class":"lineCov","hits":"1","order":"2970",},
{"lineNum":"  139","line":"  systemctl reset-failed \"${AUTO_UNIT}.service\" \"${AUTO_UNIT}.timer\" >/dev/null 2>&1 || true","class":"lineCov","hits":"1","order":"2972",},
{"lineNum":"  140","line":"}"},
{"lineNum":"  141","line":""},
{"lineNum":"  142","line":"#######################################"},
{"lineNum":"  143","line":"# Install and enable a persistent boot-time unit that revokes passwordless"},
{"lineNum":"  144","line":"# sudo on every boot. The in-session auto-revoke timer is transient and does"},
{"lineNum":"  145","line":"# NOT survive a reboot, so without this a reboot could strand the grant with"},
{"lineNum":"  146","line":"# nothing left to remove it. Idempotent; safe to leave enabled permanently"},
{"lineNum":"  147","line":"# (its `off` is a no-op when no drop-in is present)."},
{"lineNum":"  148","line":"# Globals:"},
{"lineNum":"  149","line":"#   BOOT_UNIT"},
{"lineNum":"  150","line":"#######################################"},
{"lineNum":"  151","line":"ensure_boot_revoke() {"},
{"lineNum":"  152","line":"  local self unit=\"${SYSTEMD_UNIT_DIR}/${BOOT_UNIT}.service\"","class":"lineCov","hits":"1","order":"2929",},
{"lineNum":"  153","line":"  self=\"$(readlink -f \"$0\")\"","class":"lineCov","hits":"1","order":"2931",},
{"lineNum":"  154","line":"  if [[ ! -f \"${unit}\" ]]; then","class":"lineCov","hits":"1","order":"2938",},
{"lineNum":"  155","line":"    cat >\"${unit}\" <<UNIT","class":"lineCov","hits":"1","order":"2942",},
{"lineNum":"  156","line":"[Unit]"},
{"lineNum":"  157","line":"Description=Revoke temporary passwordless sudo on boot"},
{"lineNum":"  158","line":"After=local-fs.target"},
{"lineNum":"  159","line":""},
{"lineNum":"  160","line":"[Service]"},
{"lineNum":"  161","line":"Type=oneshot"},
{"lineNum":"  162","line":"ExecStart=${self} off"},
{"lineNum":"  163","line":""},
{"lineNum":"  164","line":"[Install]"},
{"lineNum":"  165","line":"WantedBy=multi-user.target"},
{"lineNum":"  166","line":"UNIT"},
{"lineNum":"  167","line":"    systemctl daemon-reload","class":"lineCov","hits":"1","order":"2973",},
{"lineNum":"  168","line":"  fi"},
{"lineNum":"  169","line":"  systemctl enable \"${BOOT_UNIT}.service\" >/dev/null 2>&1 || true","class":"lineCov","hits":"1","order":"2974",},
{"lineNum":"  170","line":"}"},
{"lineNum":"  171","line":""},
{"lineNum":"  172","line":"#######################################"},
{"lineNum":"  173","line":"# Remove the passwordless sudo drop-in and cancel the auto-revoke timer."},
{"lineNum":"  174","line":"# Globals:"},
{"lineNum":"  175","line":"#   DROPIN"},
{"lineNum":"  176","line":"#######################################"},
{"lineNum":"  177","line":"disable_nopasswd() {"},
{"lineNum":"  178","line":"  if [[ -f \"${DROPIN}\" ]]; then","class":"lineCov","hits":"1","order":"2958",},
{"lineNum":"  179","line":"    rm -f \"${DROPIN}\"","class":"lineCov","hits":"1","order":"2960",},
{"lineNum":"  180","line":"    log_info \"passwordless sudo DISABLED (removed ${DROPIN}).\"","class":"lineCov","hits":"1","order":"2963",},
{"lineNum":"  181","line":"  else"},
{"lineNum":"  182","line":"    log_info \"already disabled (no ${DROPIN}).\"","class":"lineCov","hits":"1","order":"2965",},
{"lineNum":"  183","line":"  fi"},
{"lineNum":"  184","line":"  cancel_revoke","class":"lineCov","hits":"1","order":"2968",},
{"lineNum":"  185","line":"}"},
{"lineNum":"  186","line":""},
{"lineNum":"  187","line":"#######################################"},
{"lineNum":"  188","line":"# Report whether the drop-in is present and whether auto-revoke is armed."},
{"lineNum":"  189","line":"# Globals:"},
{"lineNum":"  190","line":"#   DROPIN"},
{"lineNum":"  191","line":"#   AUTO_UNIT"},
{"lineNum":"  192","line":"#   BOOT_UNIT"},
{"lineNum":"  193","line":"#######################################"},
{"lineNum":"  194","line":"show_status() {"},
{"lineNum":"  195","line":"  if [[ -f \"${DROPIN}\" ]]; then","class":"lineCov","hits":"1","order":"2975",},
{"lineNum":"  196","line":"    log_info \"ENABLED:\"","class":"lineCov","hits":"1","order":"2976",},
{"lineNum":"  197","line":"    sed \'s/^/  /\' \"${DROPIN}\"","class":"lineCov","hits":"1","order":"2971",},
{"lineNum":"  198","line":"  else"},
{"lineNum":"  199","line":"    log_info \"DISABLED (no ${DROPIN}).\"","class":"lineCov","hits":"1","order":"2911",},
{"lineNum":"  200","line":"  fi"},
{"lineNum":"  201","line":"  if systemctl is-active --quiet \"${AUTO_UNIT}.timer\" 2>/dev/null; then","class":"lineCov","hits":"1","order":"2910",},
{"lineNum":"  202","line":"    log_info \"auto-revoke (this session): ARMED\"","class":"lineCov","hits":"1","order":"2909",},
{"lineNum":"  203","line":"    local timers","class":"lineCov","hits":"1","order":"2908",},
{"lineNum":"  204","line":"    timers=$(systemctl list-timers \"${AUTO_UNIT}.timer\" --no-pager 2>/dev/null || true)","class":"lineCov","hits":"1","order":"2907",},
{"lineNum":"  205","line":"    sed -n \'2p\' <<<\"${timers}\" | sed \'s/^/  /\'","class":"lineCov","hits":"1","order":"2906",},
{"lineNum":"  206","line":"  else"},
{"lineNum":"  207","line":"    log_info \"auto-revoke (this session): not armed\"","class":"lineCov","hits":"1","order":"2905",},
{"lineNum":"  208","line":"  fi"},
{"lineNum":"  209","line":"  if systemctl is-enabled --quiet \"${BOOT_UNIT}.service\" 2>/dev/null; then","class":"lineCov","hits":"1","order":"2934",},
{"lineNum":"  210","line":"    log_info \"boot-revoke: enabled (passwordless sudo is cleared on every reboot)\"","class":"lineCov","hits":"1","order":"2919",},
{"lineNum":"  211","line":"  else"},
{"lineNum":"  212","line":"    log_info \"boot-revoke: NOT installed (a reboot would not clear a stale grant)\"","class":"lineCov","hits":"1","order":"2904",},
{"lineNum":"  213","line":"  fi"},
{"lineNum":"  214","line":"}"},
{"lineNum":"  215","line":""},
{"lineNum":"  216","line":"#######################################"},
{"lineNum":"  217","line":"# Entry point: dispatch on the requested action."},
{"lineNum":"  218","line":"#######################################"},
{"lineNum":"  219","line":"main() {"},
{"lineNum":"  220","line":"  case \"${1:-}\" in","class":"lineCov","hits":"1","order":"2926",},
{"lineNum":"  221","line":"    -h | --help | \"\") show_usage; exit 0 ;;","class":"lineCov","hits":"1","order":"2903",},
{"lineNum":"  222","line":"  esac"},
{"lineNum":"  223","line":"  require_root","class":"lineCov","hits":"1","order":"2940",},
{"lineNum":"  224","line":"  case \"${1}\" in","class":"lineCov","hits":"1","order":"2947",},
{"lineNum":"  225","line":"    on)"},
{"lineNum":"  226","line":"      # on [user] [minutes]; a bare numeric first arg is treated as minutes."},
{"lineNum":"  227","line":"      local user=\"\" minutes=\"${DEFAULT_TIMEOUT_MIN}\"","class":"lineCov","hits":"1","order":"2902",},
{"lineNum":"  228","line":"      if [[ \"${2:-}\" =~ ^[0-9]+$ ]]; then","class":"lineCov","hits":"1","order":"2901",},
{"lineNum":"  229","line":"        minutes=\"${2}\"","class":"lineCov","hits":"1","order":"2912",},
{"lineNum":"  230","line":"      else"},
{"lineNum":"  231","line":"        user=\"${2:-}\"","class":"lineCov","hits":"1","order":"2953",},
{"lineNum":"  232","line":"        [[ \"${3:-}\" =~ ^[0-9]+$ ]] && minutes=\"${3}\"","class":"lineCov","hits":"1","order":"2900",},
{"lineNum":"  233","line":"      fi"},
{"lineNum":"  234","line":"      # Install the boot-time safety net BEFORE granting, so a reboot can never"},
{"lineNum":"  235","line":"      # strand the grant even if everything after this point fails."},
{"lineNum":"  236","line":"      ensure_boot_revoke","class":"lineCov","hits":"1","order":"2899",},
{"lineNum":"  237","line":"      enable_nopasswd \"${user}\"","class":"lineCov","hits":"1","order":"2898",},
{"lineNum":"  238","line":"      schedule_revoke \"${minutes}\"","class":"lineCov","hits":"1","order":"2897",},
{"lineNum":"  239","line":"      ;;"},
{"lineNum":"  240","line":"    off)    disable_nopasswd ;;","class":"lineCov","hits":"1","order":"2896",},
{"lineNum":"  241","line":"    status) show_status ;;","class":"lineNoCov","hits":"0",},
{"lineNum":"  242","line":"    *)      log_error \"unknown command: ${1}\"; show_usage; exit 2 ;;","class":"lineCov","hits":"1","order":"2895",},
{"lineNum":"  243","line":"  esac"},
{"lineNum":"  244","line":"}"},
{"lineNum":"  245","line":""},
{"lineNum":"  246","line":"# Only run when executed, not when sourced — the test suite sources this file to exercise its"},
{"lineNum":"  247","line":"# individual functions."},
{"lineNum":"  248","line":"if [[ \"${BASH_SOURCE[0]}\" == \"${0}\" ]]; then","class":"lineCov","hits":"1","order":"2961",},
{"lineNum":"  249","line":"  main \"$@\"","class":"lineCov","hits":"1","order":"2894",},
{"lineNum":"  250","line":"fi"},
]};
